package localchat;
import java.awt.*;import java.awt.image.BufferedImage;import java.nio.file.*;import java.util.*;import java.util.List;import javax.swing.*;
/** Offline UI and full chat delegation monitor regression tests. */
public final class AgentPanelTest {
 static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static List<Component> all(Component component){List<Component> out=new ArrayList<>();out.add(component);if(component instanceof Container c)for(Component child:c.getComponents())out.addAll(all(child));return out;}
 static String visible(AgentPanel panel){StringBuilder b=new StringBuilder();for(Component c:all(panel)){if(c instanceof JLabel l)b.append(l.getText());if(c instanceof JTextArea a)b.append(a.getText());}return b.toString();}
 static List<ChatClient.Message> history(String result){return List.of(ChatClient.Message.user("Start agents"),ChatClient.Message.assistant("",List.of(new ChatClient.ToolCall("team","run_agents",Json.obj("tasks",List.of(Json.obj("title","PDF","task","Assigned PDF"))))),"fixture"),ChatClient.Message.toolResult("team",result,false));}
 static String result(){return Json.write(Json.obj("group_id","g","model","any-model","status","partial","tasks",List.of(Json.obj("title","Same title","task","First independent task","status","done","answer","Actual result one"),Json.obj("title","Same title","task","Second independent task","status","partial","error","tool_errors","answer","Actual partial result"))));}
 public static void main(String[] args)throws Exception{
  Files.createDirectories(Path.of(System.getProperty("localchat.home")));
  FeatureTest.edt(()->{
   int[] hidden={0},cancel={0};AgentPanel panel=new AgentPanel(()->hidden[0]++,()->cancel[0]++);panel.setSize(310,600);
   check(panel.count()==0&&!panel.stop.isEnabled(),"empty monitor never invents running agents");
   panel.queued("g-1","Same title","First independent task","any-model");panel.queued("g-2","Same title","Second independent task","any-model");panel.busy(true);check(panel.count()==2&&panel.state("g-1").equals("queued")&&panel.stop.isEnabled(),"duplicate titles retain separate queued tasks and Stop");
   panel.progress("g-1","tool:read_file");check(panel.state("g-1").equals("tool:read_file"),"live tool state visible by id");panel.result(result());check(panel.state("g-1").equals("done")&&panel.state("g-2").equals("partial"),"terminal states reflect individual actual results");check(!panel.stop.isEnabled(),"no active tasks disables Stop");
   panel.queued("active","Pending","Do work","arbitrary");panel.busy(true);panel.stop.doClick();panel.close.doClick();check(cancel[0]==1&&hidden[0]==1,"hide and stop actions delegated exactly once");
   panel.restore(history(result()));check(panel.count()==2&&!panel.task("g-1").equals(panel.task("g-2")),"reload restores exact separate task scopes");
   for(String lang:I18n.CODES)for(boolean dark:new boolean[]{false,true}){I18n.setLanguage(lang);panel.translate();panel.theme(dark);for(int pass=0;pass<3;pass++)for(Component c:all(panel))if(c instanceof Container box)box.doLayout();BufferedImage image=new BufferedImage(310,600,BufferedImage.TYPE_INT_RGB);Graphics2D graphics=image.createGraphics();panel.printAll(graphics);graphics.dispose();if(lang.equals("ro"))javax.imageio.ImageIO.write(image,"png",Path.of(System.getProperty("localchat.home")).resolve("agent-panel-"+(dark?"dark":"light")+".png").toFile());check(panel.close.getToolTipText().equals(I18n.text("Ascunde panoul agentilor")),"localized accessible monitor "+lang+dark);Color fg=panel.getForeground(),bg=panel.getBackground();check(image.getWidth()==310&&Math.abs(bg.getRed()-(dark?27:255))<2,"theme background and compact render "+lang+dark);check(all(panel).stream().filter(c->c instanceof JLabel l&&l.getText().startsWith(I18n.text("Agenti"))).allMatch(c->Math.abs(c.getForeground().getRed()-c.getParent().getBackground().getRed())>100),"heading remains readable on each theme");check(panel.count()==2,"appearance switch preserves rows");}
   I18n.setLanguage("ro");var toggles=all(panel).stream().filter(c->c instanceof JToggleButton).map(c->(JToggleButton)c).toList();toggles.get(0).doClick();check(visible(panel).contains("Actual result one"),"expand exposes actual result, not hidden raw reasoning");
   panel.restore(history(result()));check(visible(panel).contains("Actual result one"),"expanded details preserved on same-chat history refresh");panel.restore(List.of());check(panel.count()==0&&!visible(panel).contains("Actual result one"),"new chat clears prior task details");
   var noResult=List.of(ChatClient.Message.assistant("",List.of(new ChatClient.ToolCall("old","run_agents",Json.obj("tasks",List.of(Json.obj("title","old","task","unconfirmed old work"))))),"fixture"));panel.restore(noResult);check(panel.state("old-1").equals("unconfirmed"),"historical pending call is not assumed running or done");
   panel.restore(history(Json.write(Json.obj("group_id","stop","model","model","tasks",List.of(Json.obj("title","stopped","task","scope","status","cancelled","completion_pending",true))))));check(panel.state("stop-1").equals("cancelled")&&visible(panel).contains(I18n.text("Rezultatul operatiilor inca in curs nu este confirmat.")),"Stop retains explicit uncertainty about unfinished operations");
   for(int i=0;i<30;i++)panel.queued("r"+i,"Task "+i,"scope","model");check(panel.count()==AgentPanel.MAX_ROWS,"large history has bounded visible task cards");
  });
  Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");
  try(var server=new FeatureTest.Server(FeatureTest.json(AgentIntegrationTest.delegate()),FeatureTest.json(FeatureTest.answer("Child one",10,3)),FeatureTest.json(FeatureTest.answer("Child two",10,3)),FeatureTest.json(FeatureTest.answer("Combined",10,3)))){
   LocalChat[] app={null};FeatureTest.edt(()->{app[0]=AttachmentTest.window(home,server.url());app[0].setSize(1500,1000);app[0].addNotify();app[0].validate();});
   NormalModeTest.ask(app[0],"Porneste doi agenti pentru analiza independenta, fara modificari.");
   FeatureTest.edt(()->{AgentPanel panel=FeatureTest.field(app[0],"agentPanel");check(panel.count()==2&&panel.isVisible(),"real delegation opens monitor with actual children");check(visible(panel).contains("PDF")&&visible(panel).contains("Pairs"),"task identities remain visible after parent consolidation");int calls=server.requests.size();FeatureTest.call(app[0],"renderHistory",new Class<?>[]{});check(panel.count()==2&&server.requests.size()==calls,"history refresh needs no API inference");JButton button=FeatureTest.field(app[0],"agentsButton");button.doClick();check(!panel.isVisible(),"toolbar hides panel");button.doClick();check(panel.isVisible(),"toolbar reopens retained results");FeatureTest.call(app[0],"newChat",new Class<?>[]{});check(panel.count()==0&&!panel.isVisible(),"new conversation isolates agent monitor");app[0].dispose();});
  }finally{FeatureTest.edt(()->{for(Window w:Window.getWindows())w.dispose();});}System.out.println("PASS: "+checks+" agent side-panel checks; live delegation, restored evidence, chat isolation, details, Stop, six languages and themes");System.exit(0);
 }
}
